			List<LmdbNativeDecisionRecord.Entry> selected = observe();
			long runsBefore = LmdbNativeParallelPipelines.PARALLEL_ROW_RUNS.get();
			Map<Value, Long> bag = new LinkedHashMap<>();
			long rawRows = 0L;
			try (NativeUnorderedInput input = fixture.step(distinct).openUnorderedInput(fixture.row)) {
				assertThat(input.cursor).isNotNull();
				assertThat(input.batchCursor).isNull();
				assertThat(input.dedupMode).isEqualTo(NativeUnorderedInput.DedupMode.HASH);
				while (input.advance()) {
					bag.merge(fixture.evaluation.lazyValue(fixture.row.slots[1]), 1L, Long::sum);
					rawRows++;
				}
				input.markExhausted();
			} finally {
				LmdbNativeDispatchLoop.observeSelections(null);
			}
			assertThat(rawRows).isEqualTo(ROWS);
			assertThat(bag).isEqualTo(expectedBag(ROWS / KEYS));
			assertPhysicalRun(fixture, selected, runsBefore);
